namespace OrynoSync.Core;
public sealed class LocalMutationSuppression{private static readonly TimeSpan Ttl=TimeSpan.FromMinutes(10);private readonly Dictionary<string,(long,DateTimeOffset,DateTimeOffset)> _items=new(StringComparer.OrdinalIgnoreCase);public void Expect(string p,long s,DateTimeOffset m)=>_items[PathRules.NormalizeRelative(p)]=(s,m,DateTimeOffset.UtcNow);public bool IsSuppressed(string p,FileInfo? f){var k=PathRules.NormalizeRelative(p);if(!_items.TryGetValue(k,out var x))return false;if(DateTimeOffset.UtcNow-x.Item3>Ttl){_items.Remove(k);return false;}if(f is null||f.Length==x.Item1&&f.LastWriteTimeUtc==x.Item2.UtcDateTime){_items.Remove(k);return true;}return false;}
/// <summary>How long a materialisation keeps swallowing watcher events for its path. Windows raises Created + Changed (and often several Changed) for one download; the whole echo lands inside this window.</summary>
public static TimeSpan MaterialisationWindow { get; set; } = TimeSpan.FromSeconds(30);
/// <summary>True while this path is still inside the materialisation window: those events are our own write echoing back, so they must not be uploaded. The registration is NOT consumed (unlike the exact metadata match) so later echo events are swallowed too.</summary>
public bool IsMaterialisedRecently(string p){var k=PathRules.NormalizeRelative(p);if(!_items.TryGetValue(k,out var x))return false;if(DateTimeOffset.UtcNow-x.Item3>Ttl){_items.Remove(k);return false;}return DateTimeOffset.UtcNow-x.Item3<=MaterialisationWindow;}
/// <summary>Peeks without consuming, so a diagnostic can be written before the entry is spent.</summary>
public bool HasExpectation(string p){var k=PathRules.NormalizeRelative(p);return _items.TryGetValue(k,out var x)&&DateTimeOffset.UtcNow-x.Item3<=Ttl;}}
public sealed class LocalReconciler(ILocalStateStore store,IgnoreRules ignores){public async Task<IReadOnlyList<PendingOperation>> ScanAsync(string root,CancellationToken ct=default){var now=new Dictionary<string,LocalItem>(StringComparer.OrdinalIgnoreCase);if(!Directory.Exists(root))return [];foreach(var d in Directory.EnumerateDirectories(root,"*",SearchOption.AllDirectories)){var p=PathRules.ToRelative(root,d);if(!ignores.IsIgnored(p))now[p]=new(p,ItemType.Directory,0,Directory.GetLastWriteTimeUtc(d));}foreach(var f in Directory.EnumerateFiles(root,"*",SearchOption.AllDirectories)){ct.ThrowIfCancellationRequested();var p=PathRules.ToRelative(root,f);if(ignores.IsIgnored(p))continue;var i=new FileInfo(f);now[p]=new(p,ItemType.File,i.Length,i.LastWriteTimeUtc,SyncState:SyncItemState.Waiting);}var old=(await store.GetItemsAsync(ct)).ToDictionary(x=>x.RelativePath,StringComparer.OrdinalIgnoreCase);var ops=new List<PendingOperation>();foreach(var i in now.Values){if(!old.TryGetValue(i.RelativePath,out var prev)){await store.UpsertItemAsync(i,ct);ops.Add(new(Guid.NewGuid(),i.ItemType==ItemType.Directory?OperationType.CreateDirectory:OperationType.CreateFile,i.RelativePath));}else if(i.ItemType==ItemType.File&&(i.Size!=prev.Size||i.Mtime!=prev.Mtime)){await store.UpsertItemAsync(i,ct);ops.Add(new(Guid.NewGuid(),OperationType.UpdateFile,i.RelativePath));}}foreach(var m in old.Values.Where(x=>!now.ContainsKey(x.RelativePath))){await store.RemoveItemAsync(m.RelativePath,ct);ops.Add(new(Guid.NewGuid(),OperationType.Delete,m.RelativePath));}foreach(var o in ops)await store.EnqueueAsync(o,ct);return ops;}}
public sealed class DebouncedChangeProcessor(ILocalStateStore store,string root,IgnoreRules ignores,LocalMutationSuppression suppression,TimeSpan? debounce=null){private readonly TimeSpan _delay=debounce??TimeSpan.FromMilliseconds(750);private readonly Dictionary<string,CancellationTokenSource> _pending=new(StringComparer.OrdinalIgnoreCase);public event Action<ActivityEntry>? Activity;public void Observe(WatcherChangeTypes change,string path,string? oldPath=null){var r=PathRules.ToRelative(root,path);if(ignores.IsIgnored(r)||suppression.IsSuppressed(r,File.Exists(path)?new FileInfo(path):null))return;if(_pending.Remove(r,out var x))x.Cancel();var c=new CancellationTokenSource();_pending[r]=c;_=Run(change,r,oldPath,c.Token);}private async Task Run(WatcherChangeTypes c,string r,string? oldPath,CancellationToken ct){try{await Task.Delay(_delay,ct);_pending.Remove(r);var p=PathRules.ToAbsolute(root,r);if(c==WatcherChangeTypes.Deleted||!File.Exists(p)&&!Directory.Exists(p)){await store.RemoveItemAsync(r);await store.EnqueueAsync(new(Guid.NewGuid(),OperationType.Delete,r));}else if(c==WatcherChangeTypes.Renamed&&oldPath is not null)await store.EnqueueAsync(new(Guid.NewGuid(),OperationType.Move,PathRules.ToRelative(root,oldPath),r));else{var d=Directory.Exists(p);var i=d?new LocalItem(r,ItemType.Directory,0,Directory.GetLastWriteTimeUtc(p)):Stable(p,r);await store.UpsertItemAsync(i);await store.EnqueueAsync(new(Guid.NewGuid(),d?OperationType.CreateDirectory:OperationType.UpdateFile,r));}Activity?.Invoke(new(r,c.ToString(),"Waiting",DateTimeOffset.Now));}catch(OperationCanceledException){}}private static LocalItem Stable(string p,string r){var i=new FileInfo(p);return new(r,ItemType.File,i.Length,i.LastWriteTimeUtc,SyncState:SyncItemState.Waiting);}}
public sealed class LocalWatcher:IDisposable{private readonly FileSystemWatcher _w;private readonly DebouncedChangeProcessor _p;public bool IsOverflowed{get;private set;}public event Action? Overflowed;public LocalWatcher(string root,DebouncedChangeProcessor p){_p=p;_w=new(root){IncludeSubdirectories=true,NotifyFilter=NotifyFilters.FileName|NotifyFilters.DirectoryName|NotifyFilters.LastWrite|NotifyFilters.Size,InternalBufferSize=65536};_w.Created+=On;_w.Changed+=On;_w.Deleted+=On;_w.Renamed+=Renamed;_w.Error+=Error;}private void On(object? s,FileSystemEventArgs e)=>_p.Observe(e.ChangeType,e.FullPath);private void Renamed(object? s,RenamedEventArgs e)=>_p.Observe(WatcherChangeTypes.Renamed,e.FullPath,e.OldFullPath);private void Error(object? s,ErrorEventArgs e){if(e.GetException() is InternalBufferOverflowException){IsOverflowed=true;Overflowed?.Invoke();}}public void Start()=>_w.EnableRaisingEvents=true;public void Dispose()=>_w.Dispose();}
public sealed class MockSyncApi:ISyncApi{public bool Online{get;set;}=true;public TimeSpan Latency{get;set;}=TimeSpan.FromMilliseconds(30);public bool FailUploads{get;set;}public bool SimulateConflict{get;set;}public int SuccessfulOperations{get;private set;}private async Task Guard(CancellationToken c){await Task.Delay(Latency,c);if(!Online)throw new IOException("Mock server is offline.");}public Task AuthenticateAsync(CancellationToken c=default)=>Guard(c);public async Task<IReadOnlyList<string>> GetRootsAsync(CancellationToken c=default){await Guard(c);return ["root"];}public async Task<IReadOnlyList<LocalItem>> GetInventoryAsync(CancellationToken c=default){await Guard(c);return [];}public async Task CreateUploadAsync(PendingOperation o,CancellationToken c=default){await Guard(c);if(FailUploads)throw new TimeoutException("Simulated upload failure.");if(SimulateConflict)throw new InvalidOperationException("Simulated conflict.");SuccessfulOperations++;}public Task UploadChunkAsync(PendingOperation o,Stream s,CancellationToken c=default)=>Guard(c);public Task CommitUploadAsync(PendingOperation o,CancellationToken c=default)=>Guard(c);public async Task CreateDirectoryAsync(PendingOperation o,CancellationToken c=default){await Guard(c);SuccessfulOperations++;}public async Task MoveAsync(PendingOperation o,CancellationToken c=default){await Guard(c);SuccessfulOperations++;}public async Task DeleteAsync(PendingOperation o,CancellationToken c=default){await Guard(c);SuccessfulOperations++;}}
public sealed class SyncEngine(ILocalStateStore store,ISyncApi api,string root){public EngineState State{get;private set;}=EngineState.Offline;public event Action<EngineState>? StateChanged;public event Action<ActivityEntry>? Activity;public bool IsPaused{get;private set;}public void Pause(){IsPaused=true;Set(EngineState.Paused);}public void Resume(){IsPaused=false;Set(EngineState.Offline);}public async Task ProcessQueueAsync(CancellationToken c=default){if(IsPaused)return;try{Set(EngineState.Connecting);await api.AuthenticateAsync(c);Set(EngineState.Syncing);foreach(var o in await store.GetPendingAsync(DateTimeOffset.UtcNow,c)){try{switch(o.Type){case OperationType.CreateDirectory:await api.CreateDirectoryAsync(o,c);break;case OperationType.Move:await api.MoveAsync(o,c);break;case OperationType.Delete:await api.DeleteAsync(o,c);break;default:await api.CreateUploadAsync(o,c);await api.CommitUploadAsync(o,c);break;}await store.UpdateOperationAsync(o with{State=OperationState.Completed},c);Activity?.Invoke(new(o.RelativePath,o.Type.ToString(),"Synced",DateTimeOffset.Now));}catch(InvalidOperationException e){await store.UpdateOperationAsync(o with{State=OperationState.Failed,LastError=e.Message,NextAttemptAt=DateTimeOffset.MaxValue},c);}catch(Exception e){var n=o.AttemptCount+1;await store.UpdateOperationAsync(o with{State=OperationState.Failed,AttemptCount=n,LastError=e.Message,NextAttemptAt=DateTimeOffset.UtcNow.AddSeconds(Math.Min(60,Math.Pow(2,n)))},c);Set(EngineState.Offline);return;}}Set(EngineState.UpToDate);}catch{Set(EngineState.Offline);}}private void Set(EngineState s){State=s;StateChanged?.Invoke(s);}}
